/* Friends for worlds 35–40 */
Object.assign(COMPS,{
  candle:{name:'Scroll Candle',e:'🕯️',type:'stun',p:32,desc:'"Your word is a lamp to my feet and a light to my path" (Psalm 119:105). Its bright flicker can dazzle a foe so it skips its turn.'},
  quill:{name:"Scribe's Quill",e:'🪶',type:'attack',p:14,desc:'From the temple courts, where everyone was amazed at the boy Jesus\' answers (Luke 2:47). Writes a sharp reply every turn.'},
  sunset:{name:'Evening Glow',e:'🌅',type:'heal',p:12,desc:'"Stay with us, for it is nearly evening" (Luke 24:29). Its warm light makes your heart burn with joy and restores you every turn.'},
  giraffe:{name:'Royal Giraffe',e:'🦒',type:'all',p:8,desc:'From the faraway land of the queen of Ethiopia (Acts 8:27). Sees far over the desert and swings at every foe at once.'},
  basket:{name:"Wall Basket",e:'🧺',type:'shield',p:45,desc:'Saul\'s friends let him down over the Damascus wall in a basket (Acts 9:25). It catches the next hit for you.'},
  skybow:{name:'Throne Rainbow',e:'🌈',type:'heal',p:15,desc:'"A rainbow like an emerald was all around the throne" (Revelation 4:3). A sign of God\'s promise that refreshes you every turn.'}
});

/* Battle mechanic texts, cutscene banners and treasures */
Object.assign(STR.en,{
 'bm.forgot':'God\'s word was lost in the temple for years. Each right answer finds a piece of the lost book. When all 3 are found, your attacks are strong!','bm.forgot.m':'Pieces found','bm.forgot.one':'A piece of the book found!','bm.forgot.full':'The Book of the Law is found! God\'s word is remembered, and your attacks are strong!',
 'bm.hurry':'The rushing crowd hides behind a shield of hurry. Answer right in 3 different subjects to break it, like the teachers amazed at Jesus\' answers!','bm.hurry.m':'Amazing answers','bm.hurry.full':'"I must be in my Father\'s house!" Wise answers break the shield of hurry!',
 'bm.sadroad':'The sad gloom keeps growing back! Answer 3 right to break the bread with Jesus and stop it.','bm.sadroad.m':'Break the bread','bm.sadroad.full':'Their eyes were opened: it\'s Jesus! The bread is broken, and the gloom stops growing back.',
 'bm.puzzled':'"How can I understand unless someone guides me?" Bible and memory-verse answers hit hard. Other answers only hit weakly.','bm.puzzled.m':'God\'s word explains','bm.puzzled.full':'The Scripture is opened! The puzzlement clears away!',
 'bm.hardheart':'Saul\'s heart was hard and his eyes were dark. Every 3 right answers, a light from heaven blasts the gloom!','bm.hardheart.m':'Light from heaven','bm.hardheart.full':'A light from heaven! Scales fall away, and a hard heart is changed!',
 'bm.lastshadow':'Look to Jesus, the King on the throne! Every third turn your next hit counts double. The last shadow can\'t stand His light!','bm.lastshadow.m':'Look to the King','bm.lastshadow.full':'"Behold, I make all things new!" ×2','bm.lastshadow.chance':'The King is coming soon! Your next hit counts double.',
 'furn.lawscroll':'The lost Book of the Law','furn.teacherscroll':'Scroll from the temple courts','furn.emmausbread':'Bread from Emmaus','furn.isaiahscroll':'Scroll of Isaiah','furn.ananiaslamp':'Ananias\' lamp from Straight Street','furn.treeoflife':'Tree of life',
 'cut.35':'God\'s word is found again!','cut.36':'In my Father\'s house!','cut.37':'The Lord is risen indeed!','cut.38':'He went on his way rejoicing!','cut.39':'Jesus changes hearts!','cut.40':'Behold, I make all things new!'
});

/* ---------- German ---------- */
Object.assign(DE.CH,{
35:{name:'Die verlorene Schriftrolle',book:'2. Könige 22–23',foe:{name:'Vergessling',pl:'Vergesslinge',what:'Schatten, die Gott vergessen lassen'},foes:[{name:'Vergessling'},{name:'Staublicht'},{name:'Spinnwebtropfen'}],
 boss:{name:'Dunkel des Vergessens',where:'in der Tempelkammer'},guide:{name:'König Josia'},
 intro:['Willkommen in Jerusalem! Ich bin Josia. Ich wurde König, als ich erst acht Jahre alt war. Ich will tun, was dem Herrn gefällt, wie mein Vorfahre König David.','Viele Jahre lang haben die Könige vor mir Gott vergessen. Sie haben Götzen angebetet, und das Haus des Herrn wurde staubig und kaputt.','Darum habe ich Zimmerleute, Bauleute und Maurer geschickt, um den Tempel auszubessern. Während sie arbeiten, durchsucht der Hohepriester Hilkija die alten Kammern.','Vergesslinge wollen, dass alle Gottes Worte für immer vergessen. Besiege 6 Düsterlinge, dann stell dich dem Dunkel des Vergessens in der Tempelkammer.'],
 hint:'Das Dunkel des Vergessens versteckt sich in der Tempelkammer. Gottes Wort war verloren, aber man kann es wiederfinden!',
 outro:['Hilkija hat es gefunden: das Buch des Gesetzes, jahrelang verloren im Haus des Herrn! Der Schreiber Schafan hat es mir vorgelesen, und ich habe meine Kleider zerrissen. Wir hatten Gottes Worten überhaupt nicht gehorcht!','Die Prophetin Hulda sagte uns, dass Gott mein demütiges Herz gesehen hat. Da habe ich das ganze Volk versammelt, Klein und Groß, und ihnen das ganze Buch vorgelesen. Gemeinsam haben wir versprochen, dem Herrn von ganzem Herzen zu folgen.','Dann haben wir die Götzen entfernt und ein Passafest gefeiert wie seit der Zeit der Richter nicht mehr! Hier ist ein Teil der Schriftrolle. Und diese kleine Schriftrollen-Kerze möchte mit dir kommen, damit du Gottes Wort nie wieder verlierst!'],
 post:'Gottes Wort ist ein Schatz. Lies es, merk es dir und folge ihm von ganzem Herzen!',
 side:{name:'Tempelbauer',what:'Hämmer',ask:'Ich bin einer der Bauleute, die das Haus des Herrn ausbessern. Der König vertraut uns so sehr, dass niemand das Geld nachzählt! Aber ich habe 3 Hämmer verloren. Findest du sie?',thanks:'Danke! Jetzt können wir treu weiterarbeiten. Wer weiß, was wir in diesen alten Kammern noch finden? Nimm das!'},
 flav:[{name:'Hilkija der Priester',lines:['Ich sagte zum Schreiber Schafan: „Ich habe das Buch des Gesetzes im Haus des Herrn gefunden!“ Wie konnten wir es nur verlieren?']},{name:'Hulda die Prophetin',lines:['Die Männer des Königs kamen und fragten mich nach dem Buch. Ich sagte ihnen: „Weil dein Herz weich war und du dich gedemütigt hast, hat der Herr dich erhört.“']}],
 verse:{t:'Er kehrte zum Herrn um von ganzem Herzen, von ganzer Seele und mit all seiner Kraft.',r:'2. Könige 23,25'}},
36:{name:'Im Tempel',book:'Lukas 2,41–52',foe:{name:'Hetzling',pl:'Hetzlinge',what:'Schatten von Hetze und Sorge'},foes:[{name:'Hetzling'},{name:'Eilwicht'},{name:'Sorgengroll'}],
 boss:{name:'Dunkel der eiligen Menge',where:'in den Tempelhöfen'},guide:{name:'Josef aus Nazaret'},
 intro:['Schalom! Ich bin Josef, ein Zimmermann aus Nazaret. Jedes Jahr gehen Maria und ich mit unserer Familie und unseren Freunden zum Passafest nach Jerusalem.','Dieses Jahr ist Jesus zwölf Jahre alt. Als das Fest vorbei war, machten wir uns in einer großen Reisegruppe auf den Heimweg. Wir dachten, Jesus sei irgendwo bei unseren Verwandten.','Nach einem ganzen Tagesmarsch suchten wir ihn, aber er war nicht da! Wir eilten zurück nach Jerusalem. Jetzt suchen wir ihn schon seit drei Tagen.','Hetzlinge bringen alle dazu, zu hetzen und sich zu sorgen. Besiege 6 Düsterlinge, dann stell dich dem Dunkel der eiligen Menge in den Tempelhöfen.'],
 hint:'Das Dunkel der eiligen Menge wirbelt durch die Tempelhöfe. Werd langsamer: Vielleicht ist Jesus genau da, wo er sein soll!',
 outro:['Wir haben ihn gefunden! Jesus saß im Tempel mitten unter den Lehrern, hörte ihnen zu und stellte ihnen Fragen. Alle staunten über sein Verständnis und seine Antworten.','Maria sagte: „Kind, wir haben dich voller Sorge gesucht!“ Jesus antwortete: „Warum habt ihr mich gesucht? Wusstet ihr nicht, dass ich im Haus meines Vaters sein muss?“ Dann kam er mit uns nach Hause und gehorchte uns, und Maria bewahrte all das in ihrem Herzen.','Jesus nahm zu an Weisheit und Größe und an Gunst bei Gott und den Menschen. Hier ist ein Teil der Schriftrolle. Und diese kleine Schreiberfeder aus dem Tempel möchte mit dir kommen!'],
 post:'Jesus war gern im Haus seines Vaters. Auch du kannst an Weisheit zunehmen, wenn du zuhörst und gute Fragen stellst!',
 side:{name:'Cousine aus Nazaret',what:'Fladenbrote',ask:'Ich bin eine Verwandte von Jesus aus Nazaret. Wir haben Fladenbrote für den langen Heimweg eingepackt, aber in der ganzen Eile habe ich 3 davon verloren! Findest du sie?',thanks:'Danke! Wir hatten es so eilig, dass wir gar nicht gemerkt haben, dass Jesus nicht bei uns war. Nächstes Mal mache ich langsamer. Nimm das!'},
 flav:[{name:'Gesetzeslehrer',lines:['Ich lehre seit vierzig Jahren in diesen Höfen. Aber noch nie habe ich einen Jungen gehört, der so gut zuhört und so weise antwortet!']},{name:'Pilgerjunge',lines:['Jedes Jahr ziehen wir zum Passafest hinauf nach Jerusalem. Unterwegs singen wir Psalmen: „Ich freute mich, als man mir sagte: Lasst uns zum Haus des Herrn gehen!“']}],
 verse:{t:'Und Jesus nahm zu an Weisheit, Alter und Gnade bei Gott und den Menschen.',r:'Lukas 2,52'}},
37:{name:'Weg nach Emmaus',book:'Lukas 24,13–35',foe:{name:'Seufzling',pl:'Seufzlinge',what:'Schatten von Traurigkeit und verlorener Hoffnung'},foes:[{name:'Seufzling'},{name:'Dämmerlicht'},{name:'Schwertropfen'}],
 boss:{name:'Dunkel des traurigen Weges',where:'beim Dorf Emmaus'},guide:{name:'Kleopas'},
 intro:['Hallo, Freund. Ich bin Kleopas. Mein Freund und ich gehen von Jerusalem in unser Dorf Emmaus. Es ist ein langer Weg, und unsere Herzen sind schwer.','Wir sind Jesus gefolgt. Wir hatten gehofft, dass er Israel erlösen würde. Aber vor drei Tagen wurde er gekreuzigt, und wir haben gesehen, wie er in ein Grab gelegt wurde.','Heute Morgen haben einige Frauen erzählt, das Grab sei leer, und Engel hätten gesagt, dass er lebt! Aber wie kann das sein? Wir wissen nicht, was wir glauben sollen.','Seufzlinge flüstern: „Es ist vorbei. Alle Hoffnung ist weg.“ Besiege 6 Düsterlinge, dann stell dich dem Dunkel des traurigen Weges beim Dorf Emmaus.'],
 hint:'Das Dunkel des traurigen Weges wartet bei Emmaus. Geh weiter: Manchmal ist Jesus näher, als du denkst!',
 outro:['Ein Fremder ging mit uns. Angefangen bei Mose und allen Propheten erklärte er uns alles, was in den Schriften über den Christus steht. Im Dorf baten wir ihn: „Bleib bei uns, denn es will Abend werden.“','Am Tisch nahm er das Brot, dankte, brach es und gab es uns. Da wurden uns die Augen geöffnet: Es war Jesus! Und er verschwand vor unseren Augen. Wir sagten: „Brannte nicht unser Herz, als er unterwegs mit uns redete?“','Wir sind den ganzen Weg nach Jerusalem zurückgerannt, um es den anderen zu sagen: „Der Herr ist wirklich auferstanden!“ Hier ist ein Teil der Schriftrolle. Und dieses warme Abendleuchten möchte bei dir bleiben, so wie wir Jesus gebeten haben, bei uns zu bleiben!'],
 post:'Jesus geht mit dir, auch an traurigen Tagen. Schlag die Bibel auf und lass dein Herz vor Freude brennen!',
 side:{name:'Bäckerin aus Emmaus',what:'Gerstenbündel',ask:'Ich backe Brot für die Reisenden, die in Emmaus Rast machen. Aber ich habe 3 Gerstenbündel am Weg verloren! Findest du sie, bevor es Abend wird?',thanks:'Danke! Heute Abend hat Kleopas einen Gast zum Essen. Irgendwie glaube ich, dass das Brotbrechen heute ganz besonders wird. Nimm das!'},
 flav:[{name:'Freund von Kleopas',lines:['Der Fremde fragte, worüber wir reden. Wir blieben traurig stehen und sagten: „Bist du der Einzige in Jerusalem, der nicht weiß, was dort passiert ist?“']},{name:'Wanderer',lines:['Emmaus liegt etwa elf Kilometer von Jerusalem entfernt. Das ist ein weiter Weg zum Gehen – und ein weiter Weg, um im Dunkeln zurückzurennen!']}],
 verse:{t:'Brannte nicht unser Herz in uns, als er mit uns redete auf dem Weg und uns die Schrift öffnete?',r:'Lukas 24,32'}},
38:{name:'Die Wüstenstraße',book:'Apostelgeschichte 8,26–40',foe:{name:'Rätselling',pl:'Rätsellinge',what:'Schatten der Verwirrung'},foes:[{name:'Rätselling'},{name:'Trugbildlicht'},{name:'Staubtropfen'}],
 boss:{name:'Dunkel der Ratlosigkeit',where:'beim Wasser am Weg'},guide:{name:'Philippus'},
 intro:['Hallo! Ich bin Philippus. Ich erzähle den Leuten die gute Nachricht von Jesus. Ein Engel des Herrn sagte zu mir: „Geh nach Süden, auf die Straße, die von Jerusalem nach Gaza hinabführt.“','Das ist eine Wüstenstraße. Warum schickt Gott mich hierher? Aber ich bin gegangen. Und schau: Da kommt ein Wagen! Der Mann darin ist ein wichtiger Beamter aus Äthiopien, der über den Schatz der Königin wacht.','Er war in Jerusalem, um Gott anzubeten, und jetzt liest er laut aus dem Propheten Jesaja. Der Geist sagte zu mir: „Geh hin und halte dich zu diesem Wagen.“','Rätsellinge lassen Gottes Wort zu schwer erscheinen. Besiege 6 Düsterlinge, dann stell dich dem Dunkel der Ratlosigkeit beim Wasser am Weg.'],
 hint:'Das Dunkel der Ratlosigkeit wartet beim Wasser. Gottes Wort ist der Schlüssel: Antworten aus der Bibel treffen es am härtesten!',
 outro:['Ich lief zum Wagen und fragte: „Verstehst du auch, was du liest?“ Er sagte: „Wie kann ich, wenn mich niemand anleitet?“ und bat mich, mich zu ihm zu setzen.','Er las gerade: „Wie ein Lamm, das vor seinem Scherer verstummt, so tat er seinen Mund nicht auf.“ Ausgehend von diesem Bibelwort erzählte ich ihm die gute Nachricht von Jesus. Da sagte er: „Sieh, hier ist Wasser! Was hindert mich, getauft zu werden?“','Also habe ich ihn getauft, und er zog voller Freude seinen Weg! Hier ist ein Teil der Schriftrolle. Und diese große Königsgiraffe aus dem fernen Land seiner Königin möchte mit dir reisen!'],
 post:'Wenn die Bibel schwer zu verstehen ist, frag nach! Gott schickt Menschen, die uns helfen, und er erklärt sein Wort gern.',
 side:{name:'Wagenlenker',what:'Beutel mit dem Schatz der Königin',ask:'Ich lenke den Wagen für meinen Herrn. Er verwaltet den ganzen Schatz der Königin Kandake von Äthiopien. Aber auf dieser holprigen Straße sind 3 Beutel heruntergefallen! Findest du sie?',thanks:'Danke! Mein Herr sagt, er hat heute einen Schatz gefunden, der mehr wert ist als alles Gold der Königin. Nimm das!'},
 flav:[{name:'Reisender nach Gaza',lines:['Diese Straße führt bis hinunter nach Gaza. Nicht viele Leute kommen hier in die Wüste. Nur die, die Gott schickt!']},{name:'Tochter von Philippus',lines:['Später wohnte mein Vater Philippus mit meinen drei Schwestern und mir in Cäsarea. Überall, wo er hinkam, erzählte er von Jesus!']}],
 verse:{t:'Philippus aber tat seinen Mund auf und fing mit diesem Schriftwort an und erzählte ihm die gute Nachricht von Jesus.',r:'Apostelgeschichte 8,35'}},
39:{name:'Weg nach Damaskus',book:'Apostelgeschichte 9,1–22',foe:{name:'Grollling',pl:'Grolllinge',what:'Schatten von Hass und harten Herzen'},foes:[{name:'Grollling'},{name:'Finsterwicht'},{name:'Steinherzgroll'}],
 boss:{name:'Dunkel des harten Herzens',where:'auf dem Weg nach Damaskus'},guide:{name:'Hananias'},
 intro:['Friede sei mit dir. Ich bin Hananias, ein Nachfolger von Jesus hier in Damaskus. Wir haben beängstigende Nachrichten gehört: Ein Mann namens Saulus kommt, um alle zu verhaften, die Jesus folgen!','Aber auf dem Weg, kurz vor der Stadt, umstrahlte Saulus plötzlich ein Licht vom Himmel. Er fiel zu Boden und hörte eine Stimme: „Saul, Saul, was verfolgst du mich?“ Saulus fragte: „Wer bist du, Herr?“ Die Antwort: „Ich bin Jesus.“','Als Saulus aufstand, konnte er nichts sehen. Seine Begleiter führten ihn an der Hand nach Damaskus. Seit drei Tagen ist er blind, und er hat nichts gegessen und nichts getrunken.','Grolllinge füllen Herzen mit Wut und Hass. Besiege 7 Düsterlinge, dann stell dich dem Dunkel des harten Herzens auf dem Weg nach Damaskus.'],
 hint:'Das Dunkel des harten Herzens versperrt den Weg nach Damaskus. Kein Herz ist zu hart, als dass Jesus es nicht verändern könnte!',
 outro:['Der Herr sprach in einer Erscheinung zu mir: „Geh in die Gerade Straße und such Saulus.“ Ich sagte: „Herr, ich habe gehört, wie viel Böses dieser Mann deinem Volk angetan hat!“ Aber der Herr sagte: „Geh hin, denn er ist mein auserwähltes Werkzeug.“','Ich hatte Angst, aber ich ging. Ich legte ihm die Hände auf und sagte: „Bruder Saul, der Herr Jesus hat mich gesandt, damit du wieder sehen kannst und mit dem Heiligen Geist erfüllt wirst.“ Da fiel es ihm wie Schuppen von den Augen, und er konnte sehen! Er stand auf und ließ sich taufen.','Sofort fing Saulus an zu predigen, dass Jesus der Sohn Gottes ist! Hier ist ein Teil der Schriftrolle. Und dieser stabile Korb hat Saulus eines Nachts geholfen, über die Stadtmauer zu fliehen. Er möchte mit dir kommen!'],
 post:'Jesus kann jedes Herz verändern. Und manchmal bittet er uns, mutig zu sein wie Hananias und zu jemandem zu gehen, vor dem wir Angst haben.',
 side:{name:'Judas aus der Geraden Straße',what:'Brote',ask:'Ich bin Judas. Saulus wohnt in meinem Haus in der Geraden Straße. Er hat seit drei Tagen nichts gegessen! Wenn er so weit ist, braucht er etwas zu essen. Findest du 3 Brote?',thanks:'Danke! Saulus kann wieder sehen, und jetzt isst er und kommt wieder zu Kräften. Was für eine Veränderung bei diesem Mann! Nimm das.'},
 flav:[{name:'Reisebegleiter von Saulus',lines:['Wir waren mit Saulus unterwegs, als es geschah. Wir hörten die Stimme, aber wir sahen niemanden! Wir standen einfach sprachlos da.']},{name:'Jünger aus Damaskus',lines:['Saulus hat uns früher gejagt. Jetzt predigt er von Jesus, und andere wollen ihn aufhalten! Eines Nachts haben wir ihn in einem großen Korb durch eine Öffnung in der Mauer hinuntergelassen.']}],
 verse:{t:'Und sogleich predigte er in den Synagogen von Jesus, dass dieser Gottes Sohn sei.',r:'Apostelgeschichte 9,20'}},
40:{name:'Insel Patmos',book:'Offenbarung 1 · 21–22',foe:{name:'Trübling',pl:'Trüblinge',what:'die letzten Schatten der Düsternis'},foes:[{name:'Trübling'},{name:'Verblassendes Licht'},{name:'Letzte-Träne-Tropfen'}],
 boss:{name:'Der letzte Schatten',where:'auf dem Berggipfel'},guide:{name:'Der Apostel Johannes'},
 intro:['Willkommen auf Patmos, kleiner Pilger! Ich bin Johannes. Vor langer Zeit war ich ein junger Fischer in Galiläa und bin Jesus gefolgt. Jetzt bin ich sehr alt und lebe auf dieser felsigen Insel, weil ich den Menschen von ihm erzählt habe.','Am Tag des Herrn hörte ich hinter mir eine laute Stimme wie eine Posaune. Ich drehte mich um und sah Jesus, strahlend wie die Sonne! Er legte seine Hand auf mich und sagte: „Fürchte dich nicht. Ich bin der Erste und der Letzte.“','Er sagte zu mir: „Schreib auf, was du siehst.“ Dann zeigte er mir wunderbare Dinge, die noch kommen werden, Dinge voller Hoffnung für alle, die ihn lieben.','Trüblinge flüstern, dass die Traurigkeit für immer bleibt. Besiege 7 Düsterlinge, dann stell dich dem letzten Schatten auf dem Berggipfel.'],
 hint:'Der letzte Schatten wartet auf dem Berggipfel. Er ist klein und verblasst schon. Schau auf Jesus, den König, der alles neu macht!',
 outro:['Ich sah einen neuen Himmel und eine neue Erde! Die heilige Stadt, das neue Jerusalem, kam von Gott herab und strahlte wie ein Edelstein. Gott wird bei seinen Menschen wohnen. Er wird jede Träne abwischen. Kein Tod mehr, kein Weinen mehr, kein Schmerz mehr!','Ein Strom mit dem Wasser des Lebens floss vom Thron Gottes, klar wie Kristall. Zu beiden Seiten stand der Baum des Lebens, der jeden Monat Früchte trägt, und seine Blätter dienen zur Heilung. Der auf dem Thron saß, sagte: „Siehe, ich mache alles neu!“','Hier ist das allerletzte Teil der Schriftrolle des Lichts! Bring es zu Simeon in die Pilgerrast. Jesus sagt: „Ich komme bald.“ Und dieser Regenbogen, wie der um Gottes Thron, möchte mit dir kommen!'],
 post:'Jesus sagt: „Siehe, ich komme bald!“ Eines Tages wird es keine Tränen mehr geben. Bis dahin: Lass sein Licht weiter leuchten!',
 side:{name:'Fischer von Patmos',what:'Muscheln',ask:'Ich fische rund um diese Insel. Meine kleine Tochter liebt Muscheln, und ich habe ihr 3 schöne versprochen. Die Wellen haben sie weggespült! Findest du sie?',thanks:'Danke! Der alte Johannes sagt, eines Tages gibt es eine Stadt mit Toren aus Perlen. Stell dir das vor! Nimm das.'},
 flav:[{name:'Bote aus Ephesus',lines:['Johannes hat Briefe an sieben Gemeinden in Asien geschrieben. Ich bringe sie übers Meer, damit die Gemeinden ermutigt werden!']},{name:'Hirte der Insel',lines:['Johannes sagt, die neue Stadt braucht weder Sonne noch Mond, denn die Herrlichkeit Gottes erleuchtet sie. Und ihre Tore werden nie geschlossen!']}],
 verse:{t:'Siehe, ich mache alles neu.',r:'Offenbarung 21,5'}}
});
if(DE.CH&&DE.CH[18]) DE.CH[18].outro=['Die Ketten sind zerbrochen! In Philippi haben Silas und ich um Mitternacht im Gefängnis gesungen – und Gott hat die Gefängnistüren aufspringen lassen.','Jetzt reise ich nach Rom. Auch wenn ich in Ketten bin – die gute Nachricht lässt sich nicht anketten!','Hier ist ein Teil der Schriftrolle des Lichts. Und nimm dieses Segelboot mit – deine Reise geht weiter! Es gibt noch mehr von Gottes Geschichte zu entdecken.'];
